# coding=utf-8
import pymongo
import json
from bson import json_util
from bson.objectid import ObjectId

PRIORITIES = (1, 2, 3)
DEFAULT_PRIORITY = 2

DEFAULT_PAGE = 1
DEFAULT_PAGE_SIZE = 20
MAX_PAGE_SIZE = 100


class TaskDAO:

    def __init__(self, database):
        self.database = database
        self.task_collection = self.database.task

    def create(self, data):
        task = {
            'title': data.get('title'),
            'description': data.get('description'),
            'priority': data.get('priority') or DEFAULT_PRIORITY,
            'done': False
        }

        inserted_id = self.task_collection.insert_one(task).inserted_id
        task = self.task_collection.find_one({ '_id': ObjectId(inserted_id) })

        return self.to_json(task)

    def list(self, skip=0, limit=None):
        cursor = self.task_collection.find().sort([
            ('done', pymongo.ASCENDING),
            ('priority', pymongo.ASCENDING)
        ])

        if skip:
            cursor = cursor.skip(skip)

        if limit is not None:
            cursor = cursor.limit(limit)

        return self.to_json(cursor)

    def read(self, object_id):
        task = self.task_collection.find_one({ '_id': ObjectId(object_id)})
        return self.to_json(task)

    def update(self):
        pass

    def delete(self):
        pass

    def to_json(self, data):
        return json.loads(json_util.dumps(data))

