from flask import Flask, jsonify, request, abort
from task import TaskDAO, PRIORITIES, DEFAULT_PAGE, DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE
import pymongo

app = Flask('todoapp')
client = pymongo.MongoClient('mongodb://localhost')
database = client.todo_list
tasks_dao = TaskDAO(database)


@app.route('/tasks')
def list():
    page_param = request.args.get('page')
    page_size_param = request.args.get('page_size')

    try:
        page = int(page_param) if page_param is not None else DEFAULT_PAGE
        page_size = int(page_size_param) if page_size_param is not None else DEFAULT_PAGE_SIZE
    except ValueError:
        return "The fields 'page' and 'page_size' must be integers", 400

    if page <= 0 or page_size <= 0:
        return "The fields 'page' and 'page_size' must be greater than 0", 400

    if page_size > MAX_PAGE_SIZE:
        return "The field 'page_size' must not be greater than %d" % MAX_PAGE_SIZE, 400

    skip = (page - 1) * page_size

    try:
        tasks = tasks_dao.list(skip=skip, limit=page_size)
    except Exception:
        return "Unable to retrieve tasks", 500

    return jsonify(tasks), 200


@app.route('/tasks/<pk>', methods=['GET', 'PUT'])
def get(pk):
    if request.method == 'GET':
        task = tasks_dao.read(pk)
        if not task:
            return "Task not found", 404
        return jsonify(task), 200


@app.route('/tasks', methods=['POST'])
def create():
    if request.method == 'POST':
        data = request.json
        title = data.get('title', None)
        description = data.get('description', None)
        priority = data.get('priority', None)

        if not title or not description:
            return "The fields 'title' and 'description' are required", 400

        if priority is not None and (isinstance(priority, bool) or priority not in PRIORITIES):
            return "The field 'priority' must be 1 (high), 2 (medium) or 3 (low)", 400

        task = tasks_dao.create(data)

        return jsonify(task), 201


if __name__ == '__main__':
    app.run()
